function formatMessage(message: string, values?: MessageValues) {
  if (!values) return message
  return Object.entries(values).reduce(
    (result, [key, value]) => result.replaceAll(`{${key}}`, String(value)),
    message,
  )
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language] = useState<SupportedLanguage>(() => resolveBrowserLanguage())
  const value = useMemo<I18nValue>(() => ({
    language,
    locale: getLocale(language),
    // Missing keys remain visible during development so translation gaps are
    // detected instead of silently mixing another language into the screen.
    t: (key, values) => formatMessage(messages[language][key] ?? key, values),
  }), [language])

  useEffect(() => {
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : language
  }, [language])

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}
